        for k in range(200): # Search for composites up to m*200+b
            c = m * k + b
            if c > 1 and not is_prime(c):
                s_composites.append(c)

        if len(s_composites) < 5:
            continue # Too sparse, retry

        c_min = s_composites[0]
        min_sum = 2 * c_min

        # Find a suitable prime q for the proof and threshold calculation
        q_cand = [p for p in [2,3,5,7,11,13] if m % p != 0]
        if not q_cand:
            q_cand = [p for p in [2,3,5,7,11,13] if math.gcd(m, p) == 1]
        if not q_cand:
            continue # Should not happen for our choice of m
        q = rng.choice(q_cand)

        # Find a set of composites covering all residues mod q
        residue_composites = {}
