        for c in s_composites:
            if len(residue_composites) == q:
                break
            r = c % q
            if r not in residue_composites:
                residue_composites[r] = c

        if len(residue_composites) != q:
            continue # Failed to find a complete set of residues, retry

        # All N > threshold should be expressible
        threshold = max(residue_composites.values()) + c_min

        s_set = set(s_composites)
        max_unexpressible = -1
        found_any = False

        # Search for the largest unexpressible number up to the threshold
        # Start from smallest possible sum
        start_n = ((min_sum - a + m -1) // m) * m + a
        if start_n < min_sum:
            start_n += m

        for n in range(start_n, threshold + m, m):
