                    break
                c2 = n - c1
                if c2 in s_set:
                    expressible = True
                    break
            if not expressible:
                max_unexpressible = n
                found_any = True

        # The problem must have a solution, and it should not be trivial
        if found_any and max_unexpressible > min_sum:
            return {'m': m, 'b': b}

